export const downloadResume = async () => {
  try {
    const response = await fetch('/anand23.pdf');
    
    if (!response.ok) {
      throw new Error('Network response was not ok');
    }
    
    const blob = await response.blob();
    
    // Check if it's actually a PDF
    if (!blob.type.includes('pdf')) {
      console.warn('File type is not PDF, forcing download');
    }
    
    // Create a blob with PDF MIME type
    const pdfBlob = new Blob([blob], { type: 'application/pdf' });
    const blobUrl = window.URL.createObjectURL(pdfBlob);
    
    // Create download link
    const link = document.createElement('a');
    link.href = blobUrl;
    link.download = 'Anand_Kumar_Resume.pdf';
    
    // For Android, we need to ensure download attribute works
    link.setAttribute('download', 'Anand_Kumar_Resume.pdf');
    link.setAttribute('target', '_blank');
    
    document.body.appendChild(link);
    link.click();
    
    // Clean up
    setTimeout(() => {
      document.body.removeChild(link);
      window.URL.revokeObjectURL(blobUrl);
    }, 100);
    
  } catch (error) {
    console.error('Error downloading resume:', error);
    // Fallback: open in new tab
    window.open('/anand23.pdf', '_blank');
  }
};
